"""Bounded integer event import API, current implementation."""
import copy
import re

def new_state():
    return {"events": {}, "totals": {}}

def _event(value, path):
    if type(value) is not dict or set(value) != {"id", "revision", "account", "amount"}:
        raise ValueError(path + ":event_shape")
    for field in ("id", "account"):
        if type(value[field]) is not str or not re.fullmatch(r"[A-Za-z][A-Za-z0-9_]{0,15}", value[field]):
            raise ValueError(path + "." + field + ":invalid_name")
    if type(value["revision"]) is not int or not 0 <= value["revision"] <= 1000:
        raise ValueError(path + ".revision:integer_range")
    if type(value["amount"]) is not int or not -1000 <= value["amount"] <= 1000:
        raise ValueError(path + ".amount:integer_range")

def apply_batch(state, batch):
    if type(batch) is not list or len(batch) > 8:
        raise ValueError("batch:invalid_size")

    # First, validate all events in the batch
    for index, event in enumerate(batch):
        path = "batch[" + str(index) + "]"
        _event(event, path)

    # Check store capacity (at most 8 unique event IDs)
    existing_ids = set(state["events"].keys())
    new_ids = {event["id"] for event in batch}
    if len(existing_ids | new_ids) > 8:
        raise ValueError("batch:store_capacity")

    # Check for conflicts: same ID, same revision, different content
    for index, event in enumerate(batch):
        event_id = event["id"]
        event_revision = event["revision"]
        existing_event = state["events"].get(event_id)
        if existing_event is not None:
            if existing_event["revision"] == event_revision:
                # Same revision but different content - conflict
                if event != existing_event:
                    raise ValueError(path + ":revision_conflict")
            # If revision is lower, ignore this event (no change)

    # All validations passed, now apply changes atomically
    for index, event in enumerate(batch):
        path = "batch[" + str(index) + "]"
        event_id = event["id"]
        event_revision = event["revision"]
        event_amount = event["amount"]

        old_amount = state["totals"].get(event["account"], 0)
        existing_event = state["events"].get(event_id)

        if existing_event is not None:
            if existing_event["revision"] < event_revision:
                # Higher revision - replace
                old_amount = existing_event["amount"]
            else:
                # Same revision and same content - no change needed
                continue

        # Update totals: remove old contribution, add new
        if existing_event is not None:
            state["totals"][event["account"]] = state["totals"][event["account"]] - old_amount
        state["totals"][event["account"]] = state["totals"].get(event["account"], 0) + event_amount
        state["events"][event_id] = copy.deepcopy(event)

def snapshot(state):
    return {"events": [copy.deepcopy(state["events"][key]) for key in sorted(state["events"])],
            "totals": dict(sorted(state["totals"].items()))}

