import copy
import re


def new_state():
    return {"events": {}, "totals": {}}


def _event(value, path):
    if type(value) is not dict or set(value) != {"id", "revision", "account", "amount"}:
        raise ValueError(path + ":event_shape")
    for field in ("id", "account"):
        if type(value[field]) is not str or not re.fullmatch(r"[A-Za-z][A-Za-z0-9_]{0,15}", value[field]):
            raise ValueError(path + "." + field + ":invalid_name")
    if type(value["revision"]) is not int or not 0 <= value["revision"] <= 1000:
        raise ValueError(path + ".revision:integer_range")
    if type(value["amount"]) is not int or not -1000 <= value["amount"] <= 1000:
        raise ValueError(path + ".amount:integer_range")


def _is_valid_batch(batch):
    """Validate a batch for all events, but don't modify state."""
    if type(batch) is not list or len(batch) > 8:
        return False, "batch:invalid_size"
    for index, event in enumerate(batch):
        path = "batch[" + str(index) + "]"
        if type(event) is not dict or set(event) != {"id", "revision", "account", "amount"}:
            return False, path + ":event_shape"
        for field in ("id", "account"):
            if type(event[field]) is not str or not re.fullmatch(r"[A-Za-z][A-Za-z0-9_]{0,15}", event[field]):
                return False, path + "." + field + ":invalid_name"
        if type(event["revision"]) is not int or not 0 <= event["revision"] <= 1000:
            return False, path + ".revision:integer_range"
        if type(event["amount"]) is not int or not -1000 <= event["amount"] <= 1000:
            return False, path + ".amount:integer_range"
    return True, None


def _check_capacity_and_conflicts(state, batch):
    """Check store capacity (<=8 events) and conflict rules. Returns error or None."""
    # Check capacity first
    if len(state["events"]) >= 8:
        return "store_capacity"

    # Check for conflicts
    for index, event in enumerate(batch):
        path = "batch[" + str(index) + "]"
        old = state["events"].get(event["id"])
        if old is not None and event["revision"] < old["revision"]:
            return path + ":revision_downgrade"
        if old is not None and event["revision"] == old["revision"] and event != old:
            return path + ":revision_conflict"
    return None


def apply_batch(state, batch):
    """Apply a batch atomically - either all succeed or all fail."""
    # First, validate the entire batch
    is_valid, error = _is_valid_batch(batch)
    if not is_valid:
        raise ValueError(error)

    # Check capacity and conflicts
    capacity_error = _check_capacity_and_conflicts(state, batch)
    if capacity_error is not None:
        raise ValueError(capacity_error)

    # Now apply all events atomically
    for index, event in enumerate(batch):
        path = "batch[" + str(index) + "]"

        # Check downgrade (we already checked, but re-check for clarity)
        old = state["events"].get(event["id"])
        if old is not None and event["revision"] < old["revision"]:
            raise ValueError(path + ":revision_downgrade")
        if old is not None and event["revision"] == old["revision"] and event != old:
            raise ValueError(path + ":revision_conflict")

        # Replace or add the event
        old_event = state["events"].get(event["id"])
        state["events"][event["id"]] = copy.deepcopy(event)

        # Update totals: if event existed with different amount, subtract old and add new
        if old_event is not None:
            old_account = old_event["account"]
            old_amount = old_event["amount"]
            state["totals"][old_account] = state["totals"].get(old_account, 0) - old_amount

        account = event["account"]
        amount = event["amount"]
        state["totals"][account] = state["totals"].get(account, 0) + amount


def snapshot(state):
    return {"events": [copy.deepcopy(state["events"][key]) for key in sorted(state["events"])],
            "totals": dict(sorted(state["totals"].items()))}


def restore(checkpoint):
    """Restore state from a checkpoint, clearing all previous state."""
    if type(checkpoint) is not dict or set(checkpoint) != {"events", "totals"}:
        raise ValueError("checkpoint:invalid")
    events, totals = checkpoint["events"], checkpoint["totals"]
    if type(events) is not list or len(events) > 8 or type(totals) is not dict:
        raise ValueError("checkpoint:invalid")

    # Validate checkpoint events
    seen_ids = set()
    for event in events:
        if type(event) is not dict or set(event) != {"id", "revision", "account", "amount"}:
            raise ValueError("checkpoint:invalid")
        if event["id"] in seen_ids:
            raise ValueError("checkpoint:invalid")
        seen_ids.add(event["id"])
        for field in ("id", "account"):
            if type(event[field]) is not str or not re.fullmatch(r"[A-Za-z][A-Za-z0-9_]{0,15}", event[field]):
                raise ValueError("checkpoint:invalid")
        if type(event["revision"]) is not int or not 0 <= event["revision"] <= 1000:
            raise ValueError("checkpoint:invalid")
        if type(event["amount"]) is not int or not -1000 <= event["amount"] <= 1000:
            raise ValueError("checkpoint:invalid")

    # Create fresh state
    state = new_state()

    # Apply batch to restore the checkpoint
    event_store.apply_batch(state, copy.deepcopy(events))

    # Verify totals match
    if any(type(v) is not int for v in totals.values()) or state["totals"] != totals:
        raise ValueError("checkpoint:invalid")

    # Reset revisions to 0 as per spec
    for event in state["events"].values():
        event["revision"] = 0

    return state


def replay(batches, checkpoint=None):
    """Apply batches in order, optionally starting from a checkpoint."""
    if type(batches) is not list or len(batches) > 8:
        raise ValueError("batches:invalid_size")

    state = new_state() if checkpoint is None else restore(checkpoint)

    for batch in batches:
        event_store.apply_batch(state, batch)

    return state

